<script lang="ts">
import type {SearchResult} from './types';import EmptyState from './EmptyState.svelte';import Button from './Button.svelte';
let {items,query='',onSelect}:{items:SearchResult[];query?:string;onSelect?:(id:string)=>void}=$props();
let page=$state(0);const size=10;const pages=$derived(Math.max(1,Math.ceil(items.length/size)));const current=$derived(Math.min(page,pages-1));
function parts(text:string){if(!query)return [{text,hit:false}];const out:{text:string;hit:boolean}[]=[];let start=0;let at=text.toLowerCase().indexOf(query.toLowerCase());while(at>=0){out.push({text:text.slice(start,at),hit:false},{text:text.slice(at,at+query.length),hit:true});start=at+query.length;at=text.toLowerCase().indexOf(query.toLowerCase(),start);}out.push({text:text.slice(start),hit:false});return out;}
</script>
<div class="ka-results od-stack">{#each items.slice(current*size,(current+1)*size) as item (item.id)}<article><div class="ka-between"><div class="od-field"><h4>{item.title}</h4>{#if item.path}<p class="ka-help">{item.path}</p>{/if}</div>{#if onSelect}<Button variant="secondary" onclick={()=>onSelect?.(item.id)}>Open scene</Button>{/if}</div><p>{#each parts(item.excerpt) as part}{#if part.hit}<mark>{part.text}</mark>{:else}{part.text}{/if}{/each}</p></article>{:else}<EmptyState title="No results" description="Try another phrase or clear the search." icon="search"/>{/each}{#if pages>1}<div class="ka-between"><Button variant="secondary" disabled={current===0} onclick={()=>page=current-1}>Previous</Button><span>{current+1} / {pages}</span><Button variant="secondary" disabled={current===pages-1} onclick={()=>page=current+1}>Next</Button></div>{/if}</div>
